DrawingAttachment technicalPoint(DrawingSheetEditor &e,const DrawingEditorModel &model,const DrawingView &v,Vec2 point,quint64 feature=1){
 for(const auto &c:e.curves(v.id))if(c.featureId==feature)for(auto role:{DrawingPointRole::Start,DrawingPointRole::End}){const auto ref=drawingAttachment(v,c,model.snapshot,role);const auto found=resolveDrawingAttachment(v,model.snapshot,e.curves(v.id),ref);if(found.status==DrawingDimensionStatus::Ready&&distance(found.point,point)<1e-7)return ref;}
 throw std::runtime_error("punto annotazione tecnica assente");
}
